/**
 * Research participation (SRS-DAT-013): what a study subject agreed to give, item by item, as on the signed paper
 * form. Every decision is kept with its version, time and who recorded it (Profile.research, oldest first); the last
 * one is in force and decides what a research package carries (researchPackage.ts). Withdrawal is a decision too.
 */
export const RESEARCH_CONSENT_VERSION = 'R-2026.10-2';

/** The items the app records, as on the paper form (pilot protocol §11); video is added with the video feature. */
export type ResearchItem = 'core' | 'photos' | 'secondaryUse' | 'regulatory';

