export interface ResearchConsent {
  version: string;
  at: string;
  /** Who recorded it on this device (the device mode at the time). */
  by: UserRole;
  items: Record<ResearchItem, boolean>;
  /** This decision withdrew from the study (every item off). */
  withdrawn: boolean;
}

/** A decision: the optional items count only with participation (core); withdrawal clears every item. */
export function researchDecision(
  items: Partial<Record<ResearchItem, boolean>>,
  by: UserRole,
  opts: { withdrawn?: boolean; at?: Date } = {},
): ResearchConsent {
  const core = !opts.withdrawn && !!items.core;
  return {
    version: RESEARCH_CONSENT_VERSION,
    at: (opts.at ?? new Date()).toISOString(),
    by,
    items: {
      core,
      photos: core && !!items.photos,
      secondaryUse: core && !!items.secondaryUse,
      regulatory: core && !!items.regulatory,
    },
    withdrawn: !!opts.withdrawn,
  };
}

/**
 * The decision in force: the last one recorded (items an older consent version did not ask about read as no), else the
 * first-run research item of older installs (measures and face points only, under that consent's version), else null.
 */
export function researchConsentOf(p: Pick<Profile, 'consent' | 'research'> | null | undefined): ResearchConsent | null {
  const last = p?.research?.at(-1);
  if (last) return { ...last, items: { ...NO_RESEARCH_ITEMS, ...last.items } };
  if (!p?.consent.researchExport) return null;
  return {
    version: p.consent.version,
    at: p.consent.at,
    by: 'patient',
    items: { ...NO_RESEARCH_ITEMS, core: true },
    withdrawn: false,
  };
}

/** Whether a research package may be made: participating, not withdrawn. */
export const canGiveResearchData = (c: ResearchConsent | null): boolean => !!c && !c.withdrawn && c.items.core;

